/** @param {number} x @returns {number} */
function square(x) { return x * x; }

/** @param {number} x @returns {number} */
export function cappedSquare(x) { return Math.min(square(x), 3); }

/** @param {number} x @returns {number} */
export function twice(x) { return double(x); }

/** @param {number} x @returns {number} */
function double(x) { return x * 2; }

/** @param {number} x @returns {number} */
const square = (x) => x * x;

/** @param {number} x @returns {number} */
export function cappedSquare(x) { return Math.min(square(x), 3); }
